from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import Conflict, CustomerNotFound
from orders.controllers.http import (InvalidRequest, Response, bad_request, conflict, not_found,
                                     require_str)
from orders.domain.customers import TIERS, Customer


def customer_body(customer: Customer) -> dict[str, Any]:
    return {"customer_id": customer.customer_id, "name": customer.name, "email": customer.email,
            "tier": customer.tier}


class CustomerController:
    def __init__(self, service: CustomerService) -> None:
        self._service = service

    def handle_register(self, request: dict[str, Any]) -> Response:
        try:
            customer_id = require_str(request, "customer_id")
            name = require_str(request, "name")
            email = require_str(request, "email")
            tier = request.get("tier", "standard")
            if tier not in TIERS:
                raise InvalidRequest(f"tier must be one of {', '.join(TIERS)}")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            customer = self._service.register(customer_id, name, email, tier)
        except Conflict as exc:
            return conflict(exc)
        return Response(201, customer_body(customer))

    def handle_get(self, customer_id: str) -> Response:
        try:
            return Response(200, customer_body(self._service.get(customer_id)))
        except CustomerNotFound:
            return not_found("customer")

"""Order placement, lookup and cancellation.

Prices come from the catalogue, stock is checked and decremented when an
order is placed, and restored when it is cancelled.
"""

from __future__ import annotations

from collections.abc import Iterable

from orders.application.errors import Conflict, CustomerNotFound, OrderNotFound, ProductNotFound
from orders.application.pricing import discount_for
from orders.domain.orders import LineItem, Order, OrderSummary
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


class OrderService:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def place_order(self, customer_id: str, requested: Iterable[tuple[str, int]]) -> Order:
        """Place an order for ``(sku, quantity)`` pairs at current catalogue prices."""
        if self._customers.get(customer_id) is None:
            raise CustomerNotFound(customer_id)
        items = []
        for sku, quantity in requested:
            product = self._catalog.get(sku)
            if product is None or not product.active:
                raise ProductNotFound(sku)
            if self._stock.get(sku) < quantity:
                raise Conflict(f"insufficient stock for {sku}")
            items.append(LineItem(sku, quantity, product.unit_price_cents))
        for item in items:
            self._stock.set(item.sku, self._stock.get(item.sku) - item.quantity)
        order = Order(self._orders.next_id(), customer_id, tuple(items))
        self._orders.add(order)
        return order

    def get_order(self, order_id: str) -> Order:
        order = self._orders.get(order_id)
        if order is None:
            raise OrderNotFound(order_id)
        return order

    def summarize(self, order: Order) -> OrderSummary:
        customer = self._customers.get(order.customer_id)
        tier = customer.tier if customer is not None else "standard"
        subtotal = order.subtotal_cents
        discount = discount_for(subtotal, tier)
        return OrderSummary(order, subtotal, discount, subtotal - discount)

    def get_order_summary(self, order_id: str) -> OrderSummary:
        return self.summarize(self.get_order(order_id))

    def list_for_customer(self, customer_id: str) -> list[Order]:
        if self._customers.get(customer_id) is None:
            raise CustomerNotFound(customer_id)
        return self._orders.list_for_customer(customer_id)

    def cancel_order(self, order_id: str) -> Order:
        order = self.get_order(order_id)
        if order.status == "cancelled":
            raise Conflict(f"order {order_id} is already cancelled")
        for item in order.items:
            self._stock.set(item.sku, self._stock.get(item.sku) + item.quantity)
        return self._orders.set_status(order_id, "cancelled")

"""In-memory order repository."""

from __future__ import annotations

from dataclasses import replace

from orders.domain.orders import Order


class InMemoryOrderRepository:
    def __init__(self) -> None:
        self._orders: dict[str, Order] = {}
        self._next_id = 1

    def next_id(self) -> str:
        order_id = f"ord-{self._next_id:04d}"
        self._next_id += 1
        return order_id

    def add(self, order: Order) -> None:
        self._orders[order.order_id] = order

    def get(self, order_id: str) -> Order | None:
        return self._orders.get(order_id)

    def set_status(self, order_id: str, status: str) -> Order:
        order = replace(self._orders[order_id], status=status)
        self._orders[order_id] = order
        return order

    def list_for_customer(self, customer_id: str) -> list[Order]:
        # dicts preserve insertion order, so this is creation order.
        return [o for o in self._orders.values() if o.customer_id == customer_id]

    def list_all(self) -> list[Order]:
        return list(self._orders.values())

"""Order data."""

from __future__ import annotations

from dataclasses import dataclass

STATUSES = ("placed", "cancelled")


@dataclass(frozen=True)
class LineItem:
    sku: str
    quantity: int
    unit_price_cents: int

    @property
    def line_total_cents(self) -> int:
        return self.quantity * self.unit_price_cents


@dataclass(frozen=True)
class Order:
    order_id: str
    customer_id: str
    items: tuple[LineItem, ...]
    status: str = "placed"

    @property
    def subtotal_cents(self) -> int:
        return sum(item.line_total_cents for item in self.items)


@dataclass(frozen=True)
class OrderSummary:
    order: Order
    subtotal_cents: int
    discount_cents: int
    total_cents: int

"""Shared response type and request-decoding helpers for controllers."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class Response:
    status: int
    body: dict[str, Any]


class InvalidRequest(ValueError):
    pass


def bad_request(exc: Exception) -> Response:
    return Response(400, {"error": str(exc)})


def not_found(what: str) -> Response:
    return Response(404, {"error": f"{what} not found"})


def conflict(exc: Exception) -> Response:
    return Response(409, {"error": str(exc)})


def require_str(request: dict[str, Any], field: str) -> str:
    value = request.get(field)
    if not isinstance(value, str) or not value:
        raise InvalidRequest(f"{field} must be a non-empty string")
    return value


def require_positive_int(value: Any, field: str) -> int:
    if type(value) is not int or value < 1:
        raise InvalidRequest(f"{field} must be a positive integer")
    return value


def require_non_negative_int(value: Any, field: str) -> int:
    if type(value) is not int or value < 0:
        raise InvalidRequest(f"{field} must be a non-negative integer")
    return value

